sections.example:
---
import Hero from "@/components/sections/Hero.astro";
---

<Hero
  badge={{ label: "Open source, MIT licensed", href: "/changelog" }}
  title="Build your site faster"
  subtitle="Start from ready-made sections and focus on your content."
  primaryCta={{ label: "Get started", href: "/docs" }}
  secondaryCta={{ label: "Browse sections", href: "/sections" }}
/>

---
import HeroGradient from "@/components/sections/HeroGradient.astro";
---

<HeroGradient
  title="Ship faster, look better"
  subtitle="Pre-built Astro components for ambitious teams."
  badge="New release"
  primaryCta={{ label: "Browse components", href: "/sections" }}
  secondaryCta={{ label: "Read the docs", href: "/docs" }}
/>

---
import HeroSplit from "@/components/sections/HeroSplit.astro";
---

<HeroSplit
  tagline="Now in beta"
  title="Ship your product faster"
  subtitle="Pre-built components that just work."
  primaryCta={{ label: "Get started", href: "/docs" }}
  secondaryCta={{ label: "View demo", href: "/sections" }}
/>

---
import Testimonials from "@/components/sections/Testimonials.astro";
---

<Testimonials
  title="What customers say"
  testimonials={[
    {
      quote: "Replace this with a real quote you have permission to use.",
      author: "Your Customer",
      role: "Role",
      company: "Company",
    },
  ]}
/>

---
import ContentBlock from "@/components/sections/ContentBlock.astro";
import workshop from "@/assets/workshop.jpg";
---

<ContentBlock
  tagline="How we work"
  title="Every loaf is shaped by hand"
  description="We start the dough the evening before and bake from four in the morning."
  features={["Sourdough fermented for 18 hours", "Flour from a mill 30 km away"]}
  image={{ src: workshop, alt: "Baker shaping loaves on a floured wooden table" }}
  imageSide="left"
/>

---
import LogoCloud from "@/components/sections/LogoCloud.astro";
---

<LogoCloud
  title="Built with:"
  logos={[
    { name: "Astro", src: "/icons/tech/astro.svg", href: "https://astro.build" },
    { name: "Fast", icon: "zap" },
  ]}
/>

---
import Stats from "@/components/sections/Stats.astro";
---

<Stats
  title="By the numbers"
  stats={[
    { value: "16", label: "Sections", description: "Ready to combine" },
    { value: "11", label: "UI components", description: "Built on Radix UI" },
  ]}
/>

---
import Team from "@/components/sections/Team.astro";
---

<Team
  title="Meet the team"
  members={[
    {
      name: "Your Name",
      role: "Founder",
      bio: "One sentence about this person.",
      social: { github: "https://github.com/your-handle" },
    },
  ]}
/>

---
import Comparison from "@/components/sections/Comparison.astro";
---

<Comparison
  title="How we compare"
  columns={[{ name: "Us", highlighted: true }, { name: "Alternative" }]}
  features={[
    { name: "Open source", values: [true, false] },
    { name: "Updates per year", values: ["Unlimited", "4"] },
  ]}
/>
